window.AUTH=window.AUTH||{};window.AUTH["18-459"]={"d":"18-459","id":"2018/18-459","n":"Emulex Corp. v. Varjabedian","briefs":[{"k":"petitioner","label":"Brief of petitioners Emulex Corporation, et al.","date":"2019-02-19","url":"https://www.supremecourt.gov/DocketPDF/18/18-459/88873/20190219170143337_2019-02-19%20Emulex%20brief%20with%20addendum.pdf","side":"pet","n":88},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2019-02-26","url":"https://www.supremecourt.gov/DocketPDF/18/18-459/89751/20190226165255799_18-459npUnitedStates.pdf","side":"us","n":79},{"k":"respondent","label":"Brief of respondents Gary Varjabedian, et al.","date":"2019-03-21","url":"https://www.supremecourt.gov/DocketPDF/18/18-459/92772/20190321220054965_18-459%20bs.pdf","side":"res","n":74},{"k":"reply","label":"Reply of petitioners Emulex Corporation, et al.","date":"2019-04-08","url":"https://www.supremecourt.gov/DocketPDF/18/18-459/95617/20190408120733623_2019-04-08%20No.%2018-459%20Emulex%20reply%20brief.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-459_4hdj.pdf","tr":true,"items":[{"t":"case","label":"Aaron v. SEC","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"ar":4,"sum":"The Court held that plain language and the legislative history of the statutes required the SEC to establish defendant’s intent to “deceive, manipulate, or defraud” for violations of Section 10(b) and the part of Section 17(a) that specifically refers to the use of a device, scheme, or artifice with intent to defraud.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"15, 16, 17"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"passim","1":"12, 27, 29, 30, 31","2":"passim","3":"passim"}},{"t":"case","label":"Bath v. Bushkin, Gaims, Gaines & Jonas","cite":"913 F.2d 817","y":1990,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/913/817/","by":{"0":"45"}},{"t":"case","label":"Beck v. Dobrowski","cite":"559 F.3d 680","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/559/680/","by":{"0":"41","1":"23"}},{"t":"case","label":"Bell v. Cameron Meadows Land Co.","cite":"669 F.2d 1278","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/669/1278/","by":{"0":"9"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 39, 40, 42","1":"31","3":"10"}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"ar":12,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","1":"30","2":"passim","3":"6, 7"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"ar":14,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"10, 24","1":"13, 30","2":"25, 40","3":"4, 9, 18"}},{"t":"case","label":"Chris-Craft Industries, Inc. v. Piper Aircraft Corp.","cite":"480 F.2d 341","y":1973,"url":"https://www.courtlistener.com/c/F.2d/480/341/","by":{"0":"2","1":"27"}},{"t":"case","label":"Correctional Services Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Page(s) Cort v. Ash","cite":"422 U.S. 66","y":1975,"id":"1974/73-1908","sc":1,"sum":"Respondent stockholder brought this action seeking damages in favor of petitioner Bethlehem Steel Corp., a Delaware corporation, and injunctive relief because of advertisements in connection with the 1972 Presidential election that petitioner corporate directors had authorized from general corporate funds in alleged violation of 18 U. S. C. § 610, which prohibits corporations from making contributions or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"28"}},{"t":"case","label":"Currie v. Cayman Resources Corp.","cite":"835 F.2d 780","y":1988,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/835/780/","by":{"0":"45"}},{"t":"case","label":"Deviries v. Prudential-Bache Securities, Inc.","cite":"805 F.2d 326","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/805/326/","by":{"0":"45"}},{"t":"case","label":"Electronic Specialty Co. v. International Controls Corp.","cite":"409 F.2d 937","y":1969,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/409/937/","by":{"0":"9","2":"41"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"ar":5,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Finkel v. Stratton Corp.","cite":"962 F.2d 169","y":1992,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/962/169/","by":{"0":"44, 45","1":"31","3":"16"}},{"t":"case","label":"Gonzaga University v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"sum":"The Court held that such an action is foreclosed because the relevant provisions of FERPA create no personal rights to enforce.","sumSrc":"Oyez","by":{"0":"47, 48","3":"6"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","1":"16"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"J.I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"ar":1,"sum":"Respondent, stockholder of petitioner company, brought a civil action in federal court for deprivation of his and other stockholders' preemptive rights by reason of a merger involving the company, allegedly effected through use of a false and misleading proxy statement. The complaint has two counts, one based on diversity and claiming a breach of directors' fiduciary duty to stockholders and the other alleging a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 9, 20","1":"27, 28","2":"passim","3":"2"}},{"t":"case","label":"Page(s) Janus Capital Group, Inc. v. First Derivative Traders","cite":"564 U.S. 135","y":2011,"id":"2010/09-525","sc":1,"sum":"The Court held that a service provider cannot be held liable for statements for which they are not directly responsible.","sumSrc":"Oyez","by":{"0":"3, 21, 50","1":"30","3":"12"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"0":"19, 21","3":"12"}},{"t":"case","label":"Johnson v. Interstate Management Co.","cite":"849 F.3d 1093","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/849/1093/","by":{"0":"46","1":"29","2":"44"}},{"t":"case","label":"Landry v. All American Assurance Co.","cite":"688 F.2d 381","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/688/381/","by":{"0":"45"}},{"t":"case","label":"Maldonado v. Dominguez","cite":"137 F.3d 1","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/137/1/","by":{"0":"45"}},{"t":"case","label":"Massachusetts Mutual Life Insurance Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49","3":"6"}},{"t":"case","label":"Meghrig v. KFC Western, Inc.","cite":"516 U.S. 479","y":1996,"id":"1995/95-83","sc":1,"sum":"In a unanimous opinion delivered by Justice Sandra Day O'Connor the Court held that section 6972 does not authorize a private cause of action to recover the prior cost of cleaning up toxic waste that does not, at the time of suit, continue to pose an endangerment to health or the environment.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Miller v. Gammie","cite":"335 F.3d 889","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/335/889/","by":{"0":"43"}},{"t":"case","label":"Musick, Peeler & Garrett v. Employers Insurance of Wausau","cite":"508 U.S. 286","y":1993,"id":"1992/92-34","sc":1,"sum":"Defendants in a 10b-5 action have a right to seek contribution as a matter of federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 49, 50","3":"12"}},{"t":"case","label":"Newcome v. Esrey","cite":"862 F.2d 1099","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/862/1099/","by":{"0":"44"}},{"t":"case","label":"Page(s) Newman v. Prior","cite":"518 F.2d 97","y":1975,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/518/97/","by":{"0":"44"}},{"t":"case","label":"Piper v. Chris-Craft Industries, Inc.","cite":"430 U.S. 1","y":1977,"id":"1976/75-353","sc":1,"sum":"Respondent Chris-Craft Industries was the unsuccessful tender offeror in a contest for the control of a corporation. During the course of the takeover contest, Chris-Craft brought suit for damages and injunctive relief against the management of the target corporation, its investment adviser, and Bangor Punta Corp., the successful competitor, alleging, inter alia, violations of § 14 (e) and other provisions of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 9, 45, 48, 51","1":"passim","2":"passim","3":"11"}},{"t":"case","label":"Polinsky v. MCA Inc.","cite":"680 F.2d 1286","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/680/1286/","by":{"0":"23"}},{"t":"case","label":"Santa Fe Industries, Inc. v. Green","cite":"430 U.S. 462","y":1977,"id":"1976/75-1753","sc":1,"sum":"Delaware's \"short-form merger\" statute enables a parent company owning at least 90% of the stock of a subsidiary to merge with the subsidiary upon approval of the parent company's board of directors, and to make cash payments for the minority shareholders' shares. Though advance notice to or consent of the minority shareholders is not required, they must be notified within 10 days of the merger's effective date, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Schlifke v. Seafirst Corp.","cite":"866 F.2d 935","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/866/935/","by":{"0":"45"}},{"t":"case","label":"Schreiber v. Burlington Northern, Inc.","cite":"472 U.S. 1","y":1985,"id":"1984/83-2129","sc":1,"ar":5,"sum":"In December 1982, respondent Burlington Northern, Inc., made a hostile tender offer for El Paso Gas Co. to which a majority of El Paso's shareholders ultimately subscribed. Burlington did not accept the tendered shares, and instead, in January 1983, after negotiations with El Paso, announced a new and friendly takeover agreement. Pursuant to this agreement, Burlington undertook to rescind the December tender offer …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 30, 38","1":"5, 6, 22","2":"10, 20, 39"}},{"t":"case","label":"SEC v. Texas Gulf Sulphur Co.","cite":"401 F.2d 833","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/401/833/","by":{"0":"34","2":"20, 21"}},{"t":"case","label":"Smallwood v. Pearl Brewing Co.","cite":"489 F.2d 579","y":1974,"url":"https://www.courtlistener.com/c/F.2d/489/579/","by":{"0":"9","1":"27","2":"39"}},{"t":"case","label":"Stephenson v. Calpine Conifers II, Ltd.","cite":"652 F.2d 808","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/652/808/","by":{"0":"45"}},{"t":"case","label":"Stoneridge Investment Partners, LLC v. Scientific-Atlanta, Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"sum":"The Court held that, under Central Bank and Section 10(b), securities fraud plaintiffs cannot sue \"aiders and abettors\" like Scientific-Atlanta. The Court noted Congress' subsequent failure to create a right of private action against aiders and abettors in the Private Securities Litigation Reform Act for support of its position that no such right should be allowed in the present case.","sumSrc":"Oyez","by":{"0":"22, 39, 40, 50","1":"26","2":"43"}},{"t":"case","label":"Page(s) Superintendent of Insurance v. Bankers Life & Casualty Co.","cite":"404 U.S. 6","y":1971,"id":"1971/70-60","sc":1,"sum":"Section 10 (b) of the Securities Exchange Act of 1934 makes it unlawful to use \"in connection with the purchase or sale\" of any security \"any manipulative or deceptive device or contrivance\" in contravention of the Securities and Exchange Commission's rules and regulations. Section 10 (b) prohibits the use of any deceptive device in the \"sale\" of any security by \"any person,\" and it is irrelevant that Manhattan was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 50","1":"27, 28, 31"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"0":"10","2":"23"}},{"t":"case","label":"Thompson v. Thompson","cite":"484 U.S. 174","y":1988,"id":"1987/86-964","sc":1,"sum":"The PKPA does not provide an implied cause of action in federal court to determine which of two conflicting state custody decisions is valid. The context in which the PKPA was enacted-the existence of jurisdictional deadlocks among the States in custody cases and a nationwide problem of interstate parental kidnaping-suggests that Congress' principal aim was to extend the requirements of the Full Faith and Credit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 21, 46"}},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"sum":"There is no implied private cause of action for damages under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 10, 46, 48","1":"29, 30","2":"passim","3":"5, 8, 12"}},{"t":"case","label":"Transamerica Mortgage Advisors, Inc. (TAMA) v. Lewis","cite":"444 U.S. 11","y":1979,"id":"1978/77-1645","sc":1,"ar":2,"sum":"Respondent, a shareholder of petitioner Mortgage Trust of America (Trust), brought this suit in Federal District Court as a derivative action on behalf of the Trust and as a class action on behalf of the Trust's shareholders, alleging that several trustees of the Trust, its investment adviser, and two corporations affiliated with the latter, had been guilty of various frauds and breaches of fiduciary duty in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 48","1":"29, 30","2":"35"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"sum":"Section 17 (a) (1) prohibits frauds against brokers as well as investors.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37","1":"11, 15, 16, 18","2":"14, 15"}},{"t":"case","label":"United States v. O’Hagan","cite":"521 U.S. 642","y":1997,"id":"1996/96-842","sc":1,"sum":"The Court ruled that a security-trader who fails to disclose personal profits gained from reliance on exclusive information is guilty of employing \"a deceptive device...in connection with the purchase of a security.\" The security-trader knowingly abuses the duty owed toward the source of information, whether the source is the company he works for or not.","sumSrc":"Oyez","by":{"0":"6, 29","1":"21, 33","2":"20"}},{"t":"case","label":"Universities Research Association v. Coutu","cite":"450 U.S. 754","y":1981,"id":"1980/78-1945","sc":1,"sum":"The Davis-Bacon Act does not confer upon an employee a private right of action for back wages under a contract that has been administratively determined not to call for work subject to the Act and thus does not contain prevailing wage stipulations. Pp. 767-784. UNIVERSITIES RESEARCH ASSN. v. COUTU (a) While requiring that certain stipulations be placed in federal construction contracts for the benefit of mechanics …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Virginia Bankshares, Inc. v. Sandberg","cite":"501 U.S. 1083","y":1991,"id":"1990/89-1448","sc":1,"sum":"Respectively. Terms like \"high value,\" in a commercial context, are reasonably understood to rest on a factual basis, and so could be shown to be misleading by garden-variety evidence. Furthermore, they can be materially misleading even if other information is available in the statement upon which an expert could deduce that they are false. A proxy statement should inform, not challenge the reader's critical wits.","sumSrc":"Oyez","by":{"0":"10, 21, 22, 23, 39","2":"25"}},{"t":"case","label":"Page(s) Wilkie v. Robbins","cite":"551 U.S. 537","y":2007,"id":"2006/06-219","sc":1,"sum":"The Court ruled 7-2 that \"neither Bivens nor RICO gives Robbins a cause of action,\" so he could not sue the government for retaliation. In an opinion by Justice David Souter, the Court declined to extend the availability of Bivens actions to cases of retaliation for the exercise of the right to exclude the government from one's property.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"27","1":"16","2":"16"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","2":"28","3":"4"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"21","1":"28"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"0":"1, 19"}},{"t":"usc","label":"15 U.S.C. § 77k","url":"https://www.law.cornell.edu/uscode/text/15/77k","subs":["(a)","(b)(3)(B)(i)(1976)","(c)","(e)"],"stext":{"head":"§77k. Civil liabilities on account of false registration statement","paras":[[0,"(a) Persons possessing cause of action; persons liable"],[0,"In case any part of the registration statement, when such part became effective, contained an untrue statement of a material fact or omitted to state a material fact required to be stated therein or necessary to make the statements therein not misleading, any person acquiring such security (unless it is proved that at the time of such acquisition he knew of such untruth or omission) may, either at law or in equity, in any court of competent jurisdiction, sue—"],[1,"(1) every person who signed the registration statement;"],[1,"(2) every person who was a director of (or person performing similar functions) or partner in the issuer at the time of the filing of the part of the registration statement with respect to which his liability is asserted;"],[1,"(3) every person who, with his consent, is named in the registration statement as being or about to become a director, person performing similar functions, or partner;"],[1,"(4) every accountant, engineer, or appraiser, or any person whose profession gives authority to a statement made by him, who has with his consent been named as having prepared or certified any part of the registration statement, or as having prepared or certified any report or valuation which is used in connection with the registration statement, with respect to the statement in such registration statement, report, or valuation, which purports to have been prepared or certified by him;"],[1,"(5) every underwriter with respect to such security."],[0,"If such person acquired the security after the issuer has made generally available to its security holders an earning statement covering a period of at least twelve months beginning after the effective date of the registration statement, then the right of recovery under this subsection shall be conditioned on proof that such person acquired the security relying upon such untrue statement in the registration statement or relying upon the registration statement and not knowing of such omission, but such reliance may be established without proof of the reading of the registration statement by such person."],[0,"(b) Persons exempt from liability upon proof of issues"],[0,"Notwithstanding the provisions of subsection (a) no person, other than the issuer, shall be liable as provided therein who shall sustain the burden of proof—"],[1,"(1) that before the effective date of the part of the registration statement with respect to which his liability is asserted (A) he had resigned from or had taken such steps as are permitted by law to resign from, or ceased or refused to act in, every office, capacity, or relationship in which he was described in the registration statement as acting or agreeing to act, and (B) he had advised the Commission and the issuer in writing that he had taken such action and that he would not be responsible for such part of the registration statement; or"],[1,"(2) that if such part of the registration statement became effective without his knowledge, upon becoming aware of such fact he forthwith acted and advised the Commission, in accordance with paragraph (1) of this subsection, and, in addition, gave reasonable public notice that such part of the registration statement had become effective without his knowledge; or"],[1,"(3) that (A) as regards any part of the registration statement not purporting to be made on the authority of an expert, and not purporting to be a copy of or extract from a report or valuation of an expert, and not purporting to be made on the authority of a public official document or statement, he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading; and (B) as regards any part of the registration statement purporting to be made upon his authority as an expert or purporting to be a copy of or extract from a report or valuation of himself as an expert, (i) he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or (ii) such part of the registration statement did not fairly represent his statement as an expert or was not a fair copy of or extract from his report or valuation as an expert; and (C) as regards any part of the registration statement purporting to be made on the authority of an expert (other than himself) or purporting to be a copy of or extract from a report or valuation of an expert (other than himself), he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement of the expert or was not a fair copy of or extract from the report or valuation of the expert; and (D) as regards any part of the registration statement purporting to be a statement made by an official person or purporting to be a copy of or extract from a public official document, he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue, or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement made by the official person or was not a fair copy of or extract from the public official document."],[0,"(c) Standard of reasonableness"],[0,"In determining, for the purpose of paragraph (3) of subsection (b) of this section, what constitutes reasonable investigation and reasonable ground for belief, the standard of reasonableness shall be that required of a prudent man in the management of his own property."],[0,"(d) Effective date of registration statement with regard to underwriters"],[0,"If any person becomes an underwriter with respect to the security after the part of the registration statement with respect to which his liability is asserted has become effective, then for the purposes of paragraph (3) of subsection (b) of this section such part of the registration statement shall be considered as having become effective with respect to such person as of the time when he became an underwriter."],[0,"(e) Measure of damages; undertaking for payment of costs"],[0,"The suit authorized under subsection (a) may be to recover such damages as shall represent the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and (1) the value thereof as of the time such suit was brought, or (2) the price at which such security shall have been disposed of in the market before suit, or (3) the price at which such security shall have been disposed of after suit but before judgment if such damages shall be less than the damages representing the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and the value thereof as of the time such suit was brought: Provided, That if the defendant proves that any portion or all of such damages represents other than the depreciation in value of such security resulting from such part of the registration statement, with respect to which his liability is asserted, not being true or omitting to state a material fact required to be stated therein or necessary to make the statements therein not misleading, such portion of or all such damages shall not be recoverable. In no event shall any underwriter (unless such underwriter shall have knowingly received from the issuer for acting as an underwriter some benefit, directly or indirectly, in which all other underwriters similarly situated did not share in proportion to their respective interests in the underwriting) be liable in any suit or as a consequence of suits authorized under subsection (a) for damages in excess of the total price at which the securities underwritten by him and distributed to the public were offered to the public. In any suit under this or any other section of this subchapter the court may, in its discretion, require an undertaking for the payment of the costs of such suit, including reasonable attorney's fees, and if judgment shall be rendered against a party litigant, upon the motion of the other party litigant, such costs may be assessed in favor of such party litigant (whether or not such undertaking has been required) if the court believes the suit or the defense to have been without merit, in an amount sufficient to reimburse him for the reasonable expenses incurred by him, in connection with such suit, such costs to be taxed in the manner usually provided for taxing of costs in the court in which the suit was heard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77k?type=usc&year=mostrecent&link-type=html"},"head":"§77k. Civil liabilities on account of false registration statement","tname":"Commerce and Trade","by":{"0":"7, 33, 32, 24, 32","1":"32"}},{"t":"usc","label":"15 U.S.C. § 77l","url":"https://www.law.cornell.edu/uscode/text/15/77l","subs":["(a)(1)","(a)(2)"],"by":{"0":"7, 8, 24, 33"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(2)","(a)(1)"],"stext":{"head":"§77q. Fraudulent interstate transactions","paras":[[0,"(a) Use of interstate commerce for purpose of fraud or deceit"],[0,"It shall be unlawful for any person in the offer or sale of any securities (including security-based swaps) or any security-based swap agreement (as defined in section 78c(a)(78) 1 of this title) by the use of any means or instruments of transportation or communication in interstate commerce or by use of the mails, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud, or"],[1,"(2) to obtain money or property by means of any untrue statement of a material fact or any omission to state a material fact necessary in order to make the statements made, in light of the circumstances under which they were made, not misleading; or"],[1,"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser."],[0,"(b) Use of interstate commerce for purpose of offering for sale"],[0,"It shall be unlawful for any person, by the use of any means or instruments of transportation or communication in interstate commerce or by the use of the mails, to publish, give publicity to, or circulate any notice, circular, advertisement, newspaper, article, letter, investment service, or communication which, though not purporting to offer a security for sale, describes such security for a consideration received or to be received, directly or indirectly, from an issuer, underwriter, or dealer, without fully disclosing the receipt, whether past or prospective, of such consideration and the amount thereof."],[0,"(c) Exemptions of section 77c not applicable to this section"],[0,"The exemptions provided in section 77c of this title shall not apply to the provisions of this section."],[0,"(d) Authority with respect to security-based swap agreements"],[0,"The authority of the Commission under this section with respect to security-based swap agreements (as defined in section 78c(a)(78) of this title) shall be subject to the restrictions and limitations of section 77b–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77q?type=usc&year=mostrecent&link-type=html"},"head":"§77q. Fraudulent interstate transactions","tname":"Commerce and Trade","by":{"0":"37, 15, 33","1":"passim, 11, 16, 17, 17, passim","2":"passim, 11, passim"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","subs":["(b)","(b)(1976)","(d)(1)","(d)(2)"],"stext":{"head":"§77t. Injunctions and prosecution of offenses","paras":[[0,"(a) Investigation of violations"],[0,"Whenever it shall appear to the Commission, either upon complaint or otherwise, that the provisions of this subchapter, or of any rule or regulation prescribed under authority thereof, have been or are about to be violated, it may, in its discretion, either require or permit such person to file with it a statement in writing, under oath, or otherwise, as to all the facts and circumstances concerning the subject matter which it believes to be in the public interest to investigate, and may investigate such facts."],[0,"(b) Action for injunction or criminal prosecution in district court"],[0,"Whenever it shall appear to the Commission that any person is engaged or about to engage in any acts or practices which constitute or will constitute a violation of the provisions of this subchapter, or of any rule or regulation prescribed under authority thereof, the Commission may, in its discretion, bring an action in any district court of the United States, or United States court of any Territory, to enjoin such acts or practices, and upon a proper showing, a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices to the Attorney General who may, in his discretion, institute the necessary criminal proceedings under this subchapter. Any such criminal proceeding may be brought either in the district wherein the transmittal of the prospectus or security complained of begins, or in the district wherein such prospectus or security is received."],[0,"(c) Writ of mandamus"],[0,"Upon application of the Commission, the district courts of the United States and the United States courts of any Territory shall have jurisdiction to issue writs of mandamus commanding any person to comply with the provisions of this subchapter or any order of the Commission made in pursuance thereof."],[0,"(d) Money penalties in civil actions"],[0,"(1) Authority of Commission"],[1,"Whenever it shall appear to the Commission that any person has violated any provision of this subchapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 77h–1 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation."],[0,"(2) Amount of penalty"],[0,"(A) First tier"],[2,"The amount of the penalty shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (i) $5,000 for a natural person or $50,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation."],[0,"(B) Second tier"],[2,"Notwithstanding subparagraph (A), the amount of penalty for each such violation shall not exceed the greater of (i) $50,000 for a natural person or $250,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[0,"(C) Third tier"],[2,"Notwithstanding subparagraphs (A) and (B), the amount of penalty for each such violation shall not exceed the greater of (i) $100,000 for a natural person or $500,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"],[3,"(I) the violation described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement; and"],[3,"(II) such violation directly or indirectly resulted in substantial losses or created a significant risk of substantial losses to other persons."],[0,"(3) Procedures for collection"],[0,"(A) Payment of penalty to Treasury"],[2,"A penalty imposed under this section shall be payable into the Treasury of the United States, except as otherwise provided in section 7246 of this title and section 78u–6 of this title."],[0,"(B) Collection of penalties"],[2,"If a person upon whom such a penalty is imposed shall fail to pay such penalty within the time prescribed in the court's order, the Commission may refer the matter to the Attorney General who shall recover such penalty by action in the appropriate United States district court."],[0,"(C) Remedy not exclusive"],[2,"The actions authorized by this subsection may be brought in addition to any other action that the Commission or the Attorney General is entitled to bring."],[0,"(D) Jurisdiction and venue"],[2,"For purposes of section 77v of this title, actions under this section shall be actions to enforce a liability or a duty created by this subchapter."],[0,"(4) Special provisions relating to a violation of a cease-and-desist order"],[1,"In an action to enforce a cease-and-desist order entered by the Commission pursuant to section 77h–1 of this title, each separate violation of such order shall be a separate offense, except that in the case of a violation through a continuing failure to comply with such an order, each day of the failure to comply with the order shall be deemed a separate offense."],[0,"(e) Authority of court to prohibit persons from serving as officers and directors"],[0,"In any proceeding under subsection (b), the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 77q(a)(1) of this title from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(f) Prohibition of attorneys' fees paid from Commission disgorgement funds"],[0,"Except as otherwise ordered by the court upon motion by the Commission, or, in the case of an administrative action, as otherwise ordered by the Commission, funds disgorged as the result of an action brought by the Commission in Federal court, or as a result of any Commission administrative action, shall not be distributed as payment for attorneys' fees or expenses incurred by private parties seeking distribution of the disgorged funds."],[0,"(g) Authority of a court to prohibit persons from participating in an offering of penny stock"],[0,"(1) In general"],[1,"In any proceeding under subsection (a) against any person participating in, or, at the time of the alleged misconduct, who was participating in, an offering of penny stock, the court may prohibit that person from participating in an offering of penny stock, conditionally or unconditionally, and permanently or for such period of time as the court shall determine."],[0,"(2) Definition"],[1,"For purposes of this subsection, the term \"person participating in an offering of penny stock\" includes any person engaging in activities with a broker, dealer, or issuer for purposes of issuing, trading, or inducing or attempting to induce the purchase or sale of, any penny stock. The Commission may, by rule or regulation, define such term to include other activities, and may, by rule, regulation, or order, exempt any person or class of persons, in whole or in part, conditionally or unconditionally, from inclusion in such term."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77t?type=usc&year=mostrecent&link-type=html"},"head":"§77t. Injunctions and prosecution of offenses","tname":"Commerce and Trade","by":{"0":"7, 49, 36, 7, 7","3":"16"}},{"t":"usc","label":"15 U.S.C. § 78ff","url":"https://www.law.cornell.edu/uscode/text/15/78ff","subs":["(a)"],"stext":{"head":"§78ff. Penalties","paras":[[0,"(a) Willful violations; false and misleading statements"],[0,"Any person who willfully violates any provision of this chapter (other than section 78dd–1 of this title), or any rule or regulation thereunder the violation of which is made unlawful or the observance of which is required under the terms of this chapter, or any person who willfully and knowingly makes, or causes to be made, any statement in any application, report, or document required to be filed under this chapter or any rule or regulation thereunder or any undertaking contained in a registration statement as provided in subsection (d) of section 78o of this title, or by any self-regulatory organization in connection with an application for membership or participation therein or to become associated with a member thereof which statement was false or misleading with respect to any material fact, shall upon conviction be fined not more than $5,000,000, or imprisoned not more than 20 years, or both, except that when such person is a person other than a natural person, a fine not exceeding $25,000,000 may be imposed; but no person shall be subject to imprisonment under this section for the violation of any rule or regulation if he proves that he had no knowledge of such rule or regulation."],[0,"(b) Failure to file information, documents, or reports"],[0,"Any issuer which fails to file information, documents, or reports required to be filed under subsection (d) of section 78o of this title or any rule or regulation thereunder shall forfeit to the United States the sum of $100 for each and every day such failure to file shall continue. Such forfeiture, which shall be in lieu of any criminal penalty for such failure to file which might be deemed to arise under subsection (a) of this section, shall be payable into the Treasury of the United States and shall be recoverable in a civil suit in the name of the United States."],[0,"(c) Violations by issuers, officers, directors, stockholders, employees, or agents of issuers"],[0,"(1)(A) Any issuer that violates subsection (a) or (g) of section 78dd–1 of this title shall be fined not more than $2,000,000."],[0,"(B) Any issuer that violates subsection (a) or (g) of section 78dd–1 of this title shall be subject to a civil penalty of not more than $10,000 imposed in an action brought by the Commission."],[0,"(2)(A) Any officer, director, employee, or agent of an issuer, or stockholder acting on behalf of such issuer, who willfully violates subsection (a) or (g) of section 78dd–1 of this title shall be fined not more than $100,000, or imprisoned not more than 5 years, or both."],[0,"(B) Any officer, director, employee, or agent of an issuer, or stockholder acting on behalf of such issuer, who violates subsection (a) or (g) of section 78dd–1 of this title shall be subject to a civil penalty of not more than $10,000 imposed in an action brought by the Commission."],[0,"(3) Whenever a fine is imposed under paragraph (2) upon any officer, director, employee, agent, or stockholder of an issuer, such fine may not be paid, directly or indirectly, by such issuer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78ff?type=usc&year=mostrecent&link-type=html"},"head":"§78ff. Penalties","tname":"Commerce and Trade","by":{"0":"7, 49","1":"33"}},{"t":"usc","label":"15 U.S.C. § 78i","url":"https://www.law.cornell.edu/uscode/text/15/78i","subs":["(e)(1976)","(f)"],"by":{"0":"31, 8, 32"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"head":"§78j. Manipulative and deceptive devices","tname":"Commerce and Trade","by":{"0":"30","1":"passim","2":"passim"}},{"t":"usc","label":"15 U.S.C. § 78n","url":"https://www.law.cornell.edu/uscode/text/15/78n","subs":["(d)(1)","(d)(5)","(e)","(a)","(d)","(d)(4)","(a)(1)"],"stext":{"head":"§78n. Proxies","paras":[[0,"(a) Solicitation of proxies in violation of rules and regulations"],[0,"(1) It shall be unlawful for any person, by the use of the mails or by any means or instrumentality of interstate commerce or of any facility of a national securities exchange or otherwise, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors, to solicit or to permit the use of his name to solicit any proxy or consent or authorization in respect of any security (other than an exempted security) registered pursuant to section 78l of this title."],[0,"(2) The rules and regulations prescribed by the Commission under paragraph (1) may include—"],[1,"(A) a requirement that a solicitation of proxy, consent, or authorization by (or on behalf of) an issuer include a nominee submitted by a shareholder to serve on the board of directors of the issuer; and"],[1,"(B) a requirement that an issuer follow a certain procedure in relation to a solicitation described in subparagraph (A)."],[0,"(b) Giving or refraining from giving proxy in respect of any security carried for account of customer"],[0,"(1) It shall be unlawful for any member of a national securities exchange, or any broker or dealer registered under this chapter, or any bank, association, or other entity that exercises fiduciary powers, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors, to give, or to refrain from giving a proxy, consent, authorization, or information statement in respect of any security registered pursuant to section 78l of this title, or any security issued by an investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.], and carried for the account of a customer."],[0,"(2) With respect to banks, the rules and regulations prescribed by the Commission under paragraph (1) shall not require the disclosure of the names of beneficial owners of securities in an account held by the bank on December 28, 1985, unless the beneficial owner consents to the disclosure. The provisions of this paragraph shall not apply in the case of a bank which the Commission finds has not made a good faith effort to obtain such consent from such beneficial owners."],[0,"(c) Information to holders of record prior to annual or other meeting"],[0,"Unless proxies, consents, or authorizations in respect of a security registered pursuant to section 78l of this title, or a security issued by an investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.], are solicited by or on behalf of the management of the issuer from the holders of record of such security in accordance with the rules and regulations prescribed under subsection (a) of this section, prior to any annual or other meeting of the holders of such security, such issuer shall, in accordance with rules and regulations prescribed by the Commission, file with the Commission and transmit to all holders of record of such security information substantially equivalent to the information which would be required to be transmitted if a solicitation were made, but no information shall be required to be filed or transmitted pursuant to this subsection before July 1, 1964."],[0,"(d) Tender offer by owner of more than five per centum of class of securities; exceptions"],[0,"(1) It shall be unlawful for any person, directly or indirectly, by use of the mails or by any means or instrumentality of interstate commerce or of any facility of a national securities exchange or otherwise, to make a tender offer for, or a request or invitation for tenders of, any class of any equity security which is registered pursuant to section 78l of this title, or any equity security of an insurance company which would have been required to be so registered except for the exemption contained in section 78l(g)(2)(G) of this title, or any equity security issued by a a closed-end investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.], if, after consummation thereof, such person would, directly or indirectly, be the beneficial owner of more than 5 per centum of such class, unless at the time copies of the offer or request or invitation are first published or sent or given to security holders such person has filed with the Commission a statement containing such of the information specified in section 78m(d) of this title, and such additional information as the Commission may by rules and regulations prescribe as necessary or appropriate in the public interest or for the protection of investors. All requests or invitations for tenders or advertisements making a tender offer or requesting or inviting tenders of such a security shall be filed as a part of such statement and shall contain such of the information contained in such statement as the Commission may by rules and regulations prescribe. Copies of any additional material soliciting or requesting such tender offers subsequent to the initial solicitation or request shall contain such information as the Commission may by rules and regulations prescribe as necessary or appropriate in the public interest or for the protection of investors, and shall be filed with the Commission not later than the time copies of such material are first published or sent or given to security holders. Copies of all statements, in the form in which such material is furnished to security holders and the Commission, shall be sent to the issuer not later than the date such material is first published or sent or given to any security holders."],[0,"(2) When two or more persons act as a partnership, limited partnership, syndicate, or other group for the purpose of acquiring, holding, or disposing of securities of an issuer, such syndicate or group shall be deemed a \"person\" for purposes of this subsection."],[0,"(3) In determining, for purposes of this subsection, any percentage of a class of any security, such class shall be deemed to consist of the amount of the outstanding securities of such class, exclusive of any securities of such class held by or for the account of the issuer or a subsidiary of the issuer."],[0,"(4) Any solicitation or recommendation to the holders of such a security to accept or reject a tender offer or request or invitation for tenders shall be made in accordance with such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[0,"(5) Securities deposited pursuant to a tender offer or request or invitation for tenders may be withdrawn by or on behalf of the depositor at any time until the expiration of seven days after the time definitive copies of the offer or request or invitation are first published or sent or given to security holders, and at any time after sixty days from the date of the original tender offer or request or invitation, except as the Commission may otherwise prescribe by rules, regulations, or order as necessary or appropriate in the public interest or for the protection of investors."],[0,"(6) Where any person makes a tender offer, or request or invitation for tenders, for less than all the outstanding equity securities of a class, and where a greater number of securities is deposited pursuant thereto within ten days after copies of the offer or request or invitation are first published or sent or given to security holders than such person is bound or willing to take up and pay for, the securities taken up shall be taken up as nearly as may be pro rata, disregarding fractions, according to the number of securities deposited by each depositor. The provisions of this subsection shall also apply to securities deposited within ten days after notice of an increase in the consideration offered to security holders, as described in paragraph (7), is first published or sent or given to security holders."],[0,"(7) Where any person varies the terms of a tender offer or request or invitation for tenders before the expiration thereof by increasing the consideration offered to holders of such securities, such person shall pay the increased consideration to each security holder whose securities are taken up and paid for pursuant to the tender offer or request or invitation for tenders whether or not such securities have been taken up by such person before the variation of the tender offer or request or invitation."],[0,"(8) The provisions of this subsection shall not apply to any offer for, or request or invitation for tenders of, any security—"],[1,"(A) if the acquisition of such security, together with all other acquisitions by the same person of securities of the same class during the preceding twelve months, would not exceed 2 per centum of that class;"],[1,"(B) by the issuer of such security; or"],[1,"(C) which the Commission, by rules or regulations or by order, shall exempt from the provisions of this subsection as not entered into for the purpose of, and not having the effect of, changing or influencing the control of the issuer or otherwise as not comprehended within the purposes of this subsection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78n?type=usc&year=mostrecent&link-type=html"},"head":"§78n. Proxies","tname":"Commerce and Trade","by":{"0":"6, 6, passim","1":"4, 12, 23, 24, 27, 22, 5, 5, 21, passim","2":"17, passim","3":"22, 18"}},{"t":"usc","label":"15 U.S.C. § 78p","url":"https://www.law.cornell.edu/uscode/text/15/78p","subs":["(b)","(a)"],"stext":{"head":"§78p. Directors, officers, and principal stockholders","paras":[[0,"(a) Disclosures required"],[0,"(1) Directors, officers, and principal stockholders required to file"],[1,"Every person who is directly or indirectly the beneficial owner of more than 10 percent of any class of any equity security (other than an exempted security) which is registered pursuant to section 78l of this title, or who is a director or an officer of the issuer of such security, shall file the statements required by this subsection with the Commission."],[0,"(2) Time of filing"],[1,"The statements required by this subsection shall be filed—"],[2,"(A) at the time of the registration of such security on a national securities exchange or by the effective date of a registration statement filed pursuant to section 78l(g) of this title;"],[2,"(B) within 10 days after he or she becomes such beneficial owner, director, or officer, or within such shorter time as the Commission may establish by rule;"],[2,"(C) if there has been a change in such ownership, or if such person shall have purchased or sold a security-based swap agreement involving such equity security, before the end of the second business day following the day on which the subject transaction has been executed, or at such other time as the Commission shall establish, by rule, in any case in which the Commission determines that such 2-day period is not feasible."],[0,"(3) Contents of statements"],[1,"A statement filed—"],[2,"(A) under subparagraph (A) or (B) of paragraph (2) shall contain a statement of the amount of all equity securities of such issuer of which the filing person is the beneficial owner; and"],[2,"(B) under subparagraph (C) of such paragraph shall indicate ownership by the filing person at the date of filing, any such changes in such ownership, and such purchases and sales of the security-based swap agreements or security-based swaps as have occurred since the most recent such filing under such subparagraph."],[0,"(4) Electronic filing and availability"],[1,"Beginning not later than 1 year after July 30, 2002—"],[2,"(A) a statement filed under subparagraph (C) of paragraph (2) shall be filed electronically;"],[2,"(B) the Commission shall provide each such statement on a publicly accessible Internet site not later than the end of the business day following that filing; and"],[2,"(C) the issuer (if the issuer maintains a corporate website) shall provide that statement on that corporate website, not later than the end of the business day following that filing."],[0,"(b) Profits from purchase and sale of security within six months"],[0,"For the purpose of preventing the unfair use of information which may have been obtained by such beneficial owner, director, or officer by reason of his relationship to the issuer, any profit realized by him from any purchase and sale, or any sale and purchase, of any equity security of such issuer (other than an exempted security) or a security-based swap agreement involving any such equity security within any period of less than six months, unless such security or security-based swap agreement was acquired in good faith in connection with a debt previously contracted, shall inure to and be recoverable by the issuer, irrespective of any intention on the part of such beneficial owner, director, or officer in entering into such transaction of holding the security or security-based swap agreement purchased or of not repurchasing the security or security-based swap agreement sold for a period exceeding six months. Suit to recover such profit may be instituted at law or in equity in any court of competent jurisdiction by the issuer, or by the owner of any security of the issuer in the name and in behalf of the issuer if the issuer shall fail or refuse to bring such suit within sixty days after request or shall fail diligently to prosecute the same thereafter; but no such suit shall be brought more than two years after the date such profit was realized. This subsection shall not be construed to cover any transaction where such beneficial owner was not such both at the time of the purchase and sale, or the sale and purchase, of the security or security-based swap agreement or a security-based swap involved, or any transaction or transactions which the Commission by rules and regulations may exempt as not comprehended within the purpose of this subsection."],[0,"(c) Conditions for sale of security by beneficial owner, director, or officer"],[0,"It shall be unlawful for any such beneficial owner, director, or officer, directly or indirectly, to sell any equity security of such issuer (other than an exempted security), if the person selling the security or his principal (1) does not own the security sold, or (2) if owning the security, does not deliver it against such sale within twenty days thereafter, or does not within five days after such sale deposit it in the mails or other usual channels of transportation; but no person shall be deemed to have violated this subsection if he proves that notwithstanding the exercise of good faith he was unable to make such delivery or deposit within such time, or that to do so would cause undue inconvenience or expense."],[0,"(d) Securities held in investment account, transactions in ordinary course of business, and establishment of primary or secondary market"],[0,"The provisions of subsection (b) of this section shall not apply to any purchase and sale, or sale and purchase, and the provisions of subsection (c) of this section shall not apply to any sale, of an equity security not then or theretofore held by him in an investment account, by a dealer in the ordinary course of his business and incident to the establishment or maintenance by him of a primary or secondary market (otherwise than on a national securities exchange or an exchange exempted from registration under section 78e of this title) for such security. The Commission may, by such rules and regulations as it deems necessary or appropriate in the public interest, define and prescribe terms and conditions with respect to securities held in an investment account and transactions made in the ordinary course of business and incident to the establishment or maintenance of a primary or secondary market."],[0,"(e) Application of section to foreign or domestic arbitrage transactions"],[0,"The provisions of this section shall not apply to foreign or domestic arbitrage transactions unless made in contravention of such rules and regulations as the Commission may adopt in order to carry out the purposes of this section."],[0,"(f) Treatment of transactions in security futures products"],[0,"The provisions of this section shall apply to ownership of and transactions in security futures products."],[0,"(g) Limitation on Commission authority"],[0,"The authority of the Commission under this section with respect to security-based swap agreements shall be subject to the restrictions and limitations of section 78c–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78p?type=usc&year=mostrecent&link-type=html"},"head":"§78p. Directors, officers, and principal stockholders","tname":"Commerce and Trade","by":{"0":"8","1":"26"}},{"t":"usc","label":"15 U.S.C. § 78r","url":"https://www.law.cornell.edu/uscode/text/15/78r","subs":["(1976)","(a)"],"stext":{"head":"§78r. Liability for misleading statements","paras":[[0,"(a) Persons liable; persons entitled to recover; defense of good faith; suit at law or in equity; costs, etc."],[0,"Any person who shall make or cause to be made any statement in any application, report, or document filed pursuant to this chapter or any rule or regulation thereunder or any undertaking contained in a registration statement as provided in subsection (d) of section 78o of this title, which statement was at the time and in the light of the circumstances under which it was made false or misleading with respect to any material fact, shall be liable to any person (not knowing that such statement was false or misleading) who, in reliance upon such statement, shall have purchased or sold a security at a price which was affected by such statement, for damages caused by such reliance, unless the person sued shall prove that he acted in good faith and had no knowledge that such statement was false or misleading. A person seeking to enforce such liability may sue at law or in equity in any court of competent jurisdiction. In any such suit the court may, in its discretion, require an undertaking for the payment of the costs of such suit, and assess reasonable costs, including reasonable attorneys' fees, against either party litigant."],[0,"(b) Contribution"],[0,"Every person who becomes liable to make payment under this section may recover contribution as in cases of contract from any person who, if joined in the original suit, would have been liable to make the same payment."],[0,"(c) Period of limitations"],[0,"No action shall be maintained to enforce any liability created under this section unless brought within one year after the discovery of the facts constituting the cause of action and within three years after such cause of action accrued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78r?type=usc&year=mostrecent&link-type=html"},"head":"§78r. Liability for misleading statements","tname":"Commerce and Trade","by":{"0":"32, 8, 35","1":"14","3":"19"}},{"t":"usc","label":"15 U.S.C. § 78t","url":"https://www.law.cornell.edu/uscode/text/15/78t","subs":["(1976)"],"by":{"0":"32"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)(1)","(d)(3)(A)","(d)(3)(B)"],"stext":{"head":"§78u. Investigations and actions","paras":[[0,"(a) Authority and discretion of Commission to investigate violations"],[0,"(1) The Commission may, in its discretion, make such investigations as it deems necessary to determine whether any person has violated, is violating, or is about to violate any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated, or, as to any act or practice, or omission to act, while associated with a member, formerly associated with a member, the rules of a registered clearing agency in which such person is a participant, or, as to any act or practice, or omission to act, while a participant, was a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm, a person associated with such a firm, or, as to any act, practice, or omission to act, while associated with such firm, a person formerly associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the Commission shall determine, as to all the facts and circumstances concerning the matter to be investigated. The Commission is authorized in its discretion, to publish information concerning any such violations, and to investigate any facts, conditions, practices, or matters which it may deem necessary or proper to aid in the enforcement of such provisions, in the prescribing of rules and regulations under this chapter, or in securing information to serve as a basis for recommending further legislation concerning the matters to which this chapter relates."],[0,"(2) On request from a foreign securities authority, the Commission may provide assistance in accordance with this paragraph if the requesting authority states that the requesting authority is conducting an investigation which it deems necessary to determine whether any person has violated, is violating, or is about to violate any laws or rules relating to securities matters that the requesting authority administers or enforces. The Commission may, in its discretion, conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance. Such assistance may be provided without regard to whether the facts stated in the request would also constitute a violation of the laws of the United States. In deciding whether to provide such assistance, the Commission shall consider whether (A) the requesting authority has agreed to provide reciprocal assistance in securities matters to the Commission; and (B) compliance with the request would prejudice the public interest of the United States."],[0,"(b) Attendance of witnesses; production of records"],[0,"For the purpose of any such investigation, or any other proceeding under this chapter, any member of the Commission or any officer designated by it is empowered to administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the Commission deems relevant or material to the inquiry. Such attendance of witnesses and the production of any such records may be required from any place in the United States or any State at any designated place of hearing."],[0,"(c) Judicial enforcement of investigative power of Commission; refusal to obey subpena; criminal sanctions"],[0,"In case of contumacy by, or refusal to obey a subpena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. And such court may issue an order requiring such person to appear before the Commission or member or officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by such court as a contempt thereof. All process in any such case may be served in the judicial district whereof such person is an inhabitant or wherever he may be found. Any person who shall, without just cause, fail or refuse to attend and testify or to answer any lawful inquiry or to produce books, papers, correspondence, memoranda, and other records, if in his power so to do, in obedience to the subpena of the Commission, shall be guilty of a misdemeanor and, upon conviction, shall be subject to a fine of not more than $1,000 or to imprisonment for a term of not more than one year, or both."],[0,"(d) Injunction proceedings; authority of court to prohibit persons from serving as officers and directors; money penalties in civil actions; disgorgement"],[0,"(1) Whenever it shall appear to the Commission that any person is engaged or is about to engage in acts or practices constituting a violation of any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated with a member, the rules of a registered clearing agency in which such person is a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm or a person associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, it may in its discretion bring an action in the proper district court of the United States, the United States District Court for the District of Columbia, or the United States courts of any territory or other place subject to the jurisdiction of the United States, to enjoin such acts or practices, and upon a proper showing a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices as may constitute a violation of any provision of this chapter or the rules or regulations thereunder to the Attorney General, who may, in his discretion, institute the necessary criminal proceedings under this chapter."],[0,"(2) Authority of Court To Prohibit Persons From Serving as Officers and Directors.—In any proceeding under paragraph (1) of this subsection, the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 78j(b) of this title or the rules or regulations thereunder from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(3) Civil money penalties and authority to seek disgorgement.—"],[1,"(A) Authority of commission.—Whenever it shall appear to the Commission that any person has violated any provision of this chapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 78u–3 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to—"],[2,"(i) impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation; and"],[2,"(ii) require disgorgement under paragraph (7) of any unjust enrichment by the person who received such unjust enrichment as a result of such violation."],[1,"(B) Amount of penalty.—"],[2,"(i) First tier.—The amount of a civil penalty imposed under subparagraph (A)(i) shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (I) $5,000 for a natural person or $50,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation."],[2,"(ii) Second tier.—Notwithstanding clause (i), the amount of a civil penalty imposed under subparagraph (A)(i) for each such violation shall not exceed the greater of (I) $50,000 for a natural person or $250,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in subparagraph (A) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[2,"(iii) Third tier.—Notwithstanding clauses (i) and (ii), the amount of a civil penalty imposed under subparagraph (A)(i) for each violation described in that subparagraph shall not exceed the greater of (I) $100,000 for a natural person or $500,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u?type=usc&year=mostrecent&link-type=html"},"head":"§78u. Investigations and actions","tname":"Commerce and Trade","by":{"0":"7, 7, 49, 7","1":"33"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(b)(2)(A)","(b)","(b)(1)(A)","(b)(1)(B)","(c)"],"stext":{"head":"§78u–4. Private securities litigation","paras":[[0,"(a) Private class actions"],[0,"(1) In general"],[1,"The provisions of this subsection shall apply in each private action arising under this chapter that is brought as a plaintiff class action pursuant to the Federal Rules of Civil Procedure."],[0,"(2) Certification filed with complaint"],[0,"(A) In general"],[2,"Each plaintiff seeking to serve as a representative party on behalf of a class shall provide a sworn certification, which shall be personally signed by such plaintiff and filed with the complaint, that—"],[3,"(i) states that the plaintiff has reviewed the complaint and authorized its filing;"],[3,"(ii) states that the plaintiff did not purchase the security that is the subject of the complaint at the direction of plaintiff's counsel or in order to participate in any private action arising under this chapter;"],[3,"(iii) states that the plaintiff is willing to serve as a representative party on behalf of a class, including providing testimony at deposition and trial, if necessary;"],[3,"(iv) sets forth all of the transactions of the plaintiff in the security that is the subject of the complaint during the class period specified in the complaint;"],[3,"(v) identifies any other action under this chapter, filed during the 3-year period preceding the date on which the certification is signed by the plaintiff, in which the plaintiff has sought to serve as a representative party on behalf of a class; and"],[3,"(vi) states that the plaintiff will not accept any payment for serving as a representative party on behalf of a class beyond the plaintiff's pro rata share of any recovery, except as ordered or approved by the court in accordance with paragraph (4)."],[0,"(B) Nonwaiver of attorney-client privilege"],[2,"The certification filed pursuant to subparagraph (A) shall not be construed to be a waiver of the attorney-client privilege."],[0,"(3) Appointment of lead plaintiff"],[0,"(A) Early notice to class members"],[0,"(i) In general"],[3,"Not later than 20 days after the date on which the complaint is filed, the plaintiff or plaintiffs shall cause to be published, in a widely circulated national business-oriented publication or wire service, a notice advising members of the purported plaintiff class—"],[4,"(I) of the pendency of the action, the claims asserted therein, and the purported class period; and"],[4,"(II) that, not later than 60 days after the date on which the notice is published, any member of the purported class may move the court to serve as lead plaintiff of the purported class."],[0,"(ii) Multiple actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter is filed, only the plaintiff or plaintiffs in the first filed action shall be required to cause notice to be published in accordance with clause (i)."],[0,"(iii) Additional notices may be required under Federal rules"],[3,"Notice required under clause (i) shall be in addition to any notice required pursuant to the Federal Rules of Civil Procedure."],[0,"(B) Appointment of lead plaintiff"],[0,"(i) In general"],[3,"Not later than 90 days after the date on which a notice is published under subparagraph (A)(i), the court shall consider any motion made by a purported class member in response to the notice, including any motion by a class member who is not individually named as a plaintiff in the complaint or complaints, and shall appoint as lead plaintiff the member or members of the purported plaintiff class that the court determines to be most capable of adequately representing the interests of class members (hereafter in this paragraph referred to as the \"most adequate plaintiff\") in accordance with this subparagraph."],[0,"(ii) Consolidated actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter has been filed, and any party has sought to consolidate those actions for pretrial purposes or for trial, the court shall not make the determination required by clause (i) until after the decision on the motion to consolidate is rendered. As soon as practicable after such decision is rendered, the court shall appoint the most adequate plaintiff as lead plaintiff for the consolidated actions in accordance with this paragraph."],[0,"(iii) Rebuttable presumption"],[0,"(I) In general"],[4,"Subject to subclause (II), for purposes of clause (i), the court shall adopt a presumption that the most adequate plaintiff in any private action arising under this chapter is the person or group of persons that—"],[5,"(aa) has either filed the complaint or made a motion in response to a notice under subparagraph (A)(i);"],[5,"(bb) in the determination of the court, has the largest financial interest in the relief sought by the class; and"],[5,"(cc) otherwise satisfies the requirements of Rule 23 of the Federal Rules of Civil Procedure."],[0,"(II) Rebuttal evidence"],[4,"The presumption described in subclause (I) may be rebutted only upon proof by a member of the purported plaintiff class that the presumptively most adequate plaintiff—"],[5,"(aa) will not fairly and adequately protect the interests of the class; or"],[5,"(bb) is subject to unique defenses that render such plaintiff incapable of adequately representing the class."],[0,"(iv) Discovery"],[3,"For purposes of this subparagraph, discovery relating to whether a member or members of the purported plaintiff class is the most adequate plaintiff may be conducted by a plaintiff only if the plaintiff first demonstrates a reasonable basis for a finding that the presumptively most adequate plaintiff is incapable of adequately representing the class."],[0,"(v) Selection of lead counsel"],[3,"The most adequate plaintiff shall, subject to the approval of the court, select and retain counsel to represent the class."],[0,"(vi) Restrictions on professional plaintiffs"],[3,"Except as the court may otherwise permit, consistent with the purposes of this section, a person may be a lead plaintiff, or an officer, director, or fiduciary of a lead plaintiff, in no more than 5 securities class actions brought as plaintiff class actions pursuant to the Federal Rules of Civil Procedure during any 3-year period."],[0,"(4) Recovery by plaintiffs"],[1,"The share of any final judgment or of any settlement that is awarded to a representative party serving on behalf of a class shall be equal, on a per share basis, to the portion of the final judgment or settlement awarded to all other members of the class. Nothing in this paragraph shall be construed to limit the award of reasonable costs and expenses (including lost wages) directly relating to the representation of the class to any representative party serving on behalf of a class."],[0,"(5) Restrictions on settlements under seal"],[1,"The terms and provisions of any settlement agreement of a class action shall not be filed under seal, except that on motion of any party to the settlement, the court may order filing under seal for those portions of a settlement agreement as to which good cause is shown for such filing under seal. For purposes of this paragraph, good cause shall exist only if publication of a term or provision of a settlement agreement would cause direct and substantial harm to any party."],[0,"(6) Restrictions on payment of attorneys' fees and expenses"],[1,"Total attorneys' fees and expenses awarded by the court to counsel for the plaintiff class shall not exceed a reasonable percentage of the amount of any damages and prejudgment interest actually paid to the class."],[0,"(7) Disclosure of settlement terms to class members"],[1,"Any proposed or final settlement agreement that is published or otherwise disseminated to the class shall include each of the following statements, along with a cover page summarizing the information contained in such statements:"],[0,"(A) Statement of plaintiff recovery"],[2,"The amount of the settlement proposed to be distributed to the parties to the action, determined in the aggregate and on an average per share basis."],[0,"(B) Statement of potential outcome of case"],[0,"(i) Agreement on amount of damages"],[3,"If the settling parties agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement concerning the average amount of such potential damages per share."],[0,"(ii) Disagreement on amount of damages"],[3,"If the parties do not agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement from each settling party concerning the issue or issues on which the parties disagree."],[0,"(iii) Inadmissibility for certain purposes"],[3,"A statement made in accordance with clause (i) or (ii) concerning the amount of damages shall not be admissible in any Federal or State judicial action or administrative proceeding, other than an action or proceeding arising out of such statement."],[0,"(C) Statement of attorneys' fees or costs sought"],[2,"If any of the settling parties or their counsel intend to apply to the court for an award of attorneys' fees or costs from any fund established as part of the settlement, a statement indicating which parties or counsel intend to make such an application, the amount of fees and costs that will be sought (including the amount of such fees and costs determined on an average per share basis), and a brief explanation supporting the fees and costs sought. Such information shall be clearly summarized on the cover page of any notice to a party of any proposed or final settlement agreement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-4?type=usc&year=mostrecent&link-type=html"},"head":"§78u–4. Private securities litigation","tname":"Commerce and Trade","by":{"0":"10","1":"33","2":"18, 22, 24, 42, 22, 22, 22, 24"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"1","2":"1"}},{"t":"law","label":"Pub. L. No. 90-439","url":"https://www.govinfo.gov/link/statute/82/454","by":{"0":"6","1":"5"}},{"t":"law","label":"Pub. L. No. 91-567","url":"https://www.govinfo.gov/link/statute/84/1497","by":{"0":"6","1":"6","2":"41"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"0":"10","1":"33","2":"22, 42, 43","3":"9"}},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","by":{"0":"3, 5","2":"passim"}},{"t":"reg","label":"17 C.F.R. § 240.14d-101","url":"https://www.ecfr.gov/current/title-17/section-240.14d-101","by":{"0":"11"}},{"t":"case","label":"Adams v. Standard Knitting Mills, Inc.","cite":"623 F.2d 422","y":1980,"url":"https://www.courtlistener.com/c/F.2d/623/422/","by":{"1":"23","2":"19","3":"22"}},{"t":"case","label":"(III) Cases—Continued: CTS Corp. v. Dynamics Corp. of Am.","cite":"481 U.S. 69","y":1987,"id":"1986/86-71","sc":1,"sum":"The federal Williams Act and implementing regulations govern hostile corporate stock tender offers by requiring, inter alia, that offers remain open for at least 20 business days. An Indiana Act applies to certain business corporations chartered in Indiana that have specified levels of shares or shareholders within the State and that opt into the Act's protection. The Indiana Act provides that the acquisition of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Caterpillar Inc. v. Lewis","cite":"519 U.S. 61","y":1996,"id":"1996/95-1263","sc":1,"sum":"A failure to remand a case improperly removed is not fatal to federal adjudication of the case so long as federal jurisdictional requirements are met at the time judgment is entered. When a diversity case has been tried in federal court under state rules of decision, the importance of finality, efficiency and economy in judicial determinations becomes decisive.","sumSrc":"Oyez","by":{"1":"28","3":"3"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Gerstle v. Gamble-Skogmo, Inc.","cite":"478 F.2d 1281","y":1973,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/478/1281/","sum":"Explaining that a person may be liable for communicating false information about a transaction in which he has a pecuniary interest “if he fails to exercise reasonable care or competence in obtaining or communicating the information”.","sumSrc":"brief:1","by":{"1":"23, 25","2":"20, 21"}},{"t":"case","label":"Gould v. American-Hawaiian S.S. Co.","cite":"535 F.2d 761","y":1976,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/535/761/","by":{"1":"23"}},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"ar":1,"sum":"Alleging that they were defrauded by misrepresentations in a registration statement and prospectus for certain securities, purchasers of such securities brought a class action in Federal District Court against most of the participants in the offering, seeking recovery under § 10(b) of the Securities Exchange Act of 1934 (1934 Act), which makes it unlawful for \"any\" person to use \"any\" manipulative or deceptive …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30","2":"18, 31, 45"}},{"t":"case","label":"Morrison v. National Austl. Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Omnicare, Inc. v. Laborers Dist. Council Constr. Indus. Pension Fund","cite":"135 S. Ct. 1318","y":2015,"id":"2014/13-435","sc":1,"sum":"The Court ruled that a statement of opinion, even if shown to be objectively false, cannot constitute an untrue statement of fact because of the different nature between opinions and facts.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Richland v. Crandall","cite":"262 F. Supp. 538","y":1967,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./262/538/","by":{"1":"23"}},{"t":"case","label":"Rondeau v. Mosinee Paper Corp.","cite":"422 U.S. 49","y":1975,"id":"1974/74-415","sc":1,"sum":"A showing of irreparable harm, in accordance with traditional principles of equity, is necessary before a private litigant can obtain injunctive relief based upon § 13 (d) of the Securities Exchange Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"SEC v. Capital Gains Research Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"by":{"1":"2, 26"}},{"t":"case","label":"SEC v. Dain Rauscher, Inc.","cite":"254 F.3d 852","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/254/852/","by":{"1":"24"}},{"t":"case","label":"Shidler v. All Am. Life & Fin. Corp.","cite":"775 F.2d 917","y":1985,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/775/917/","sum":"Describing strict liability as “too blunt a tool to ferret out the kind of deceptive practices Congress sought to prevent in enacting section 14(a)”.","sumSrc":"brief:1","by":{"1":"23, 24, 26"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"ar":3,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"United States v. Woods","cite":"571 U.S. 31","y":2013,"id":"2013/12-562","sc":1,"sum":"The Court held that, under the Tax Equity and Fiscal Responsibility Act of 1982, a court in partnership-level proceedings has the right to consider the applicability of any penalty that relates to the partnership.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"usc","label":"15 U.S.C. § 80b-6","url":"https://www.law.cornell.edu/uscode/text/15/80b-6","by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 77e","url":"https://www.law.cornell.edu/uscode/text/15/77e","by":{"1":"4, 26"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 78m","url":"https://www.law.cornell.edu/uscode/text/15/78m","subs":["(d)"],"by":{"1":"26"}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","by":{"1":"26"}},{"t":"usc","label":"15 U.S.C. § 78q","url":"https://www.law.cornell.edu/uscode/text/15/78q","subs":["(a)"],"by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 78t-1","url":"https://www.law.cornell.edu/uscode/text/15/78t-1","subs":["(a)","(d)"],"stext":{"head":"§78t–1. Liability to contemporaneous traders for insider trading","paras":[[0,"(a) Private rights of action based on contemporaneous trading"],[0,"Any person who violates any provision of this chapter or the rules or regulations thereunder by purchasing or selling a security while in possession of material, nonpublic information shall be liable in an action in any court of competent jurisdiction to any person who, contemporaneously with the purchase or sale of securities that is the subject of such violation, has purchased (where such violation is based on a sale of securities) or sold (where such violation is based on a purchase of securities) securities of the same class."],[0,"(b) Limitations on liability"],[0,"(1) Contemporaneous trading actions limited to profit gained or loss avoided"],[1,"The total amount of damages imposed under subsection (a) shall not exceed the profit gained or loss avoided in the transaction or transactions that are the subject of the violation."],[0,"(2) Offsetting disgorgements against liability"],[1,"The total amount of damages imposed against any person under subsection (a) shall be diminished by the amounts, if any, that such person may be required to disgorge, pursuant to a court order obtained at the instance of the Commission, in a proceeding brought under section 78u(d) of this title relating to the same transaction or transactions."],[0,"(3) Controlling person liability"],[1,"No person shall be liable under this section solely by reason of employing another person who is liable under this section, but the liability of a controlling person under this section shall be subject to section 78t(a) of this title."],[0,"(4) Statute of limitations"],[1,"No action may be brought under this section more than 5 years after the date of the last transaction that is the subject of the violation."],[0,"(c) Joint and several liability for communicating"],[0,"Any person who violates any provision of this chapter or the rules or regulations thereunder by communicating material, nonpublic information shall be jointly and severally liable under subsection (a) with, and to the same extent as, any person or persons liable under subsection (a) to whom the communication was directed."],[0,"(d) Authority not to restrict other express or implied rights of action"],[0,"Nothing in this section shall be construed to limit or condition the right of any person to bring an action to enforce a requirement of this chapter or the availability of any cause of action implied from a provision of this chapter."],[0,"(e) Provisions not to affect public prosecutions"],[0,"This section shall not be construed to bar or limit in any manner any action by the Commission or the Attorney General under any other provision of this chapter, nor shall it bar or limit in any manner any action to recover penalties, or to seek any other order regarding penalties."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78t-1?type=usc&year=mostrecent&link-type=html"},"head":"§78t–1. Liability to contemporaneous traders for insider trading","tname":"Commerce and Trade","by":{"1":"32","2":"41, 41"}},{"t":"usc","label":"15 U.S.C. § 78w","url":"https://www.law.cornell.edu/uscode/text/15/78w","subs":["(a)"],"by":{"1":"7, 20"}},{"t":"usc","label":"15 U.S.C. § 78aa","url":"https://www.law.cornell.edu/uscode/text/15/78aa","by":{"1":"33"}},{"t":"usc","label":"15 U.S.C. § 77p","url":"https://www.law.cornell.edu/uscode/text/15/77p","subs":["(d)(1)(B)(ii)"],"by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 11","url":"https://www.law.cornell.edu/uscode/text/15/11","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 12","url":"https://www.law.cornell.edu/uscode/text/15/12","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 15","url":"https://www.law.cornell.edu/uscode/text/15/15","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 80b-3","url":"https://www.law.cornell.edu/uscode/text/15/80b-3","by":{"1":"26"}},{"t":"reg","label":"7 Fed. Reg. 3804","url":"https://www.govinfo.gov/link/fr/7/3804","by":{"1":"3"}},{"t":"case","label":"Bath Indus., Inc. v. Blot","cite":"427 F.2d 97","y":1970,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/427/97/","by":{"2":"36"}},{"t":"case","label":"Caleb & Co. v. E.I. Du Pont de Nemours & Co.","cite":"615 F. Supp. 96","y":1985,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./615/96/","by":{"2":"41"}},{"t":"case","label":"Casey’s Gen. Stores, Inc. v. Alimentation Couche-Tard, Inc.","cite":"2010 U.S. Dist. LEXIS 101129","y":2010,"court":"S.D. Iowa Sep. 8","by":{"2":"38"}},{"t":"case","label":"Chaidez v. United States","cite":"568 U.S. 342","y":2010,"id":"2012/11-820","sc":1,"sum":"The Court found that the Padilla rule created an entirely new rule regarding ineffective assistance of counsel and therefore did not apply to persons whose conviction became final before its announcement.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"DeKalb Cty. Pension Fund v. Transocean Ltd.","cite":"817 F.3d 393","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/817/393/","by":{"2":"19"}},{"t":"case","label":"Feldbaum v. Avon Prods., Inc.","cite":"741 F.2d 234","y":1984,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/741/234/","by":{"2":"40"}},{"t":"case","label":"Garcia v. United States","cite":"469 U.S. 70","y":1984,"id":"1984/83-6061","sc":1,"sum":"The language \"any money or other property of the United States\" in § 2114 includes the $1,800 belonging to the United States and entrusted to the Secret Service agent as \"flash money,\" and thus by using a pistol in an effort to rob the agent petitioners fell squarely within the prohibitions of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Gas Nat. v. E.ON AG","cite":"468 F. Supp. 2d 595","y":2006,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/468/595/","by":{"2":"38"}},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"H. K. Porter Co. v. Nicholson File Co.","cite":"482 F.2d 421","y":1973,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/482/421/","by":{"2":"18"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Indiana Nat’l Corp. v. Rich","cite":"712 F.2d 1180","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/712/1180/","by":{"2":"31, 41"}},{"t":"case","label":"Lane v. United States","cite":"286 F.3d 723","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/286/723/","by":{"2":"15"}},{"t":"case","label":"Matrixx Initiatives, Inc. v. Siracusano","cite":"563 U.S. 27","y":2011,"id":"2010/09-1156","sc":1,"sum":"The Court held that a plaintiff could state a claim based on a pharmaceutical company's non-disclosure of adverse event reports, even though the reports are not alleged to be statistically significant.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"McFarland v. Wells Fargo Bank, N.A.","cite":"810 F.3d 273","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/273/","by":{"2":"14"}},{"t":"case","label":"Pryor v. U.S. Steel Corp.","cite":"591 F. Supp. 942","y":1984,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./591/942/","by":{"2":"13"}},{"t":"case","label":"Stevens v. Employer-Teamsters Joint Council No. 84 Pension Fund","cite":"979 F.2d 444","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/979/444/","by":{"2":"14"}},{"t":"case","label":"Stull v. Bayard","cite":"561 F.2d 429","y":1977,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/561/429/","by":{"2":"40"}},{"t":"case","label":"Susquehanna Corp. v. Pan Am. Sulphur Co.","cite":"423 F.2d 1075","y":1970,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/423/1075/","by":{"2":"41"}},{"t":"case","label":"Taro Pharm. Indus. v. Sun Pharm. Indus.","cite":"2010 U.S. Dist. LEXIS 84163","y":2010,"court":"S.D.N.Y. July 13","by":{"2":"38"}},{"t":"case","label":"Taylor v. Freeland & Kronz","cite":"503 U.S. 638","y":1992,"id":"1991/91-571","sc":1,"sum":"A trustee may not contest the validity of a claimed exemption after the Rule 4003(b) 30-day period has expired, even though the debtor had no colorable basis for claiming the exemption..","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"TSC Indus., Inc. v. Northway, Inc.","cite":"426 U.S. 438","y":1976,"id":"1975/74-1471","sc":1,"sum":"Rule 14a-9, promulgated under § 14 (a) of the Securities Exchange Act of 1934, provides that no proxy solicitation shall be made \"which... is false or misleading with respect to any material fact, or which omits to state any material fact necessary in order to make the statements therein not false or misleading.\" The dispute in this case centers on the acquisition of petitioner TSC Industries (TSC) by petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"United States v. Dunkel","cite":"927 F.2d 955","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/927/955/","by":{"2":"27"}},{"t":"case","label":"United States v. Sheldon","cite":"755 F.3d 1047","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/755/1047/","by":{"2":"14"}},{"t":"case","label":"United States v. United Foods, Inc.","cite":"533 U.S. 405","y":2001,"id":"2000/00-276","sc":1,"sum":"The Court held that the assessment requirement violates the First Amendment.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Youakim v. Miller","cite":"425 U.S. 231","y":1976,"id":"1975/73-6935","sc":1,"sum":"Although appellants' complaint described their action challenging the foster care payment scheme provided by Illinois as part of the federal Aid to Families with Dependent Children program as an action seeking an injunction on equal protection grounds, and it does not appear that appellants separately relied on the Supremacy Clause or that the District Court, in holding that the scheme did not deny appellants equal …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"law","label":"Insider Trading and Securities Fraud Enforcement Act, Pub. L. No. 100-704","url":"https://www.govinfo.gov/link/statute/102/4680","by":{"2":"41"}},{"t":"usc","label":"15 U.S.C. § 78u-5","url":"https://www.law.cornell.edu/uscode/text/15/78u-5","subs":["(b)(2)(C)","(c)(1)"],"by":{"2":"42, 42"}},{"t":"reg","label":"17 C.F.R. § 240.14a","url":"https://www.ecfr.gov/current/title-17/section-240.14a","by":{"2":"passim"}},{"t":"rule","label":"Fed. R. Civ. P. 11","url":"https://www.law.cornell.edu/rules/frcp/rule_11","by":{"2":"24"}},{"t":"case","label":"Cowin v. Bresler","cite":"741 F.2d 410","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/741/410/","by":{"3":"10"}},{"t":"case","label":"Dura Pharmaceuticals, Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"sum":"The Court held that an inflated purchase price did not by itself prove \"loss causation.\" At most, an inflated purchase price suggested that misrepresentation \"touched upon\" a later economic loss, but did not necessarily cause it.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Lebron v. National Railroad Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"3, 5"}},{"t":"case","label":"Lorenzo v. SEC","cite":"2019 WL 1369839","y":2019,"court":"U.S. Mar. 27","sum":"Recognizing that Rule 10b-5 has both “‘general’” and “‘specific proscription[s]’” that reach the same conduct, which “‘might in other circumstances be deemed “surplusage”’” (citation omitted).","sumSrc":"brief:3","by":{"3":"14"}},{"t":"case","label":"Page(s) Sinovac Biotech Ltd. v. 1Globe Capital LLC","cite":"2018 WL 5017918","y":2018,"court":"D. Mass. Oct. 15","by":{"3":"10"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"135 S. Ct. 1625","y":2015,"id":"2014/13-1074","sc":1,"ar":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Yovino v. Rizo","cite":"139 S. Ct. 706","y":2019,"id":"2018/18-272","sc":1,"sum":"The Ninth Circuit erred when it counted as a member of the majority a judge who died before the court’s opinion in this case was filed.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"4"}},{"t":"reg","label":"17 C.F.R. § 240.14a-1","url":"https://www.ecfr.gov/current/title-17/section-240.14a-1","by":{"3":"22"}},{"t":"reg","label":"17 C.F.R. § 240.14a-9","url":"https://www.ecfr.gov/current/title-17/section-240.14a-9","by":{"3":"22"}}]};